#!/usr/bin/env python3
"""Build an offline, self-contained screenshot review from a JSON report."""
import argparse,base64,html,json
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('report',type=Path);args=p.parse_args()
data=json.loads(args.report.read_text());folder=args.report.parent
esc=html.escape
cards=[]
for i,step in enumerate(data['steps'],1):
    image=base64.b64encode((folder/step['image']).read_bytes()).decode()
    cards.append(f'''<article id="step-{i}" class="step"><div class="step-head"><span class="number">{i:02}</span><div><span class="eyebrow">{esc(step['phase'])}</span><h2>{esc(step['title'])}</h2></div><span class="badge {esc(step.get('status','pass'))}">{esc(step.get('label','Проверено'))}</span></div><p>{esc(step['description'])}</p><button class="shot" aria-label="Увеличить снимок: {esc(step['title'])}"><img src="data:image/png;base64,{image}" alt="{esc(step['title'])}" loading="lazy"></button><div class="comment"><label for="note-{i}">Ваш комментарий к этому шагу</label><textarea id="note-{i}" data-step="{i}" placeholder="Что изменить в тексте, поведении или интерфейсе?"></textarea></div></article>''')
checks=''.join(f'<li><span>✓</span>{esc(x)}</li>' for x in data['checks'])
issues=''.join(f'<li>{esc(x)}</li>' for x in data['observations'])
nav=''.join(f'<a href="#step-{i}">{i:02} · {esc(s["title"])}</a>' for i,s in enumerate(data['steps'],1))
meta=''.join(f'<div><dt>{esc(k)}</dt><dd>{esc(str(v))}</dd></div>' for k,v in data['environment'].items())
page=r'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AGI OS · Реальная установка E2E</title><style>
:root{--ink:#182e32;--muted:#617578;--line:#d8e2de;--green:#12694f;--paper:#f4f6f2}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.55 system-ui,-apple-system,sans-serif}header{background:#153c36;color:white;padding:48px max(28px,calc((100vw - 1240px)/2)) 40px}header .eyebrow{color:#93d4ba}h1{font-size:clamp(30px,4vw,52px);line-height:1.1;letter-spacing:-1.8px;margin:12px 0 20px}header p{max-width:880px;color:#d8e9e2}h2{font-size:23px;line-height:1.25;margin:4px 0}h3{margin:0 0 14px}.eyebrow{font-size:12px;font-weight:750;letter-spacing:1.3px;text-transform:uppercase}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:24px}button{font:inherit;cursor:pointer}.actions button{padding:10px 16px;border:1px solid #81b09d;border-radius:8px;background:#fff;color:#153c36}.actions .secondary{background:transparent;color:white}#save-state{font-size:13px;align-self:center;color:#c9e0d7}.layout{max-width:1296px;margin:auto;display:grid;grid-template-columns:224px minmax(0,1fr);gap:30px;padding:32px 28px}aside{position:sticky;top:20px;align-self:start;font-size:13px;max-height:90vh;overflow:auto}aside strong{display:block;margin-bottom:12px}aside a{display:block;padding:7px 0;color:var(--muted);text-decoration:none}aside a:hover{color:var(--green)}.summary,.step,.observations{background:white;border:1px solid var(--line);border-radius:14px;margin-bottom:24px;padding:26px}.summary ul{padding:0;list-style:none;display:grid;grid-template-columns:1fr 1fr;gap:10px 24px}.summary li span{color:var(--green);font-weight:800;margin-right:9px}.step{scroll-margin-top:18px}.step-head{display:flex;gap:14px;align-items:center}.number{background:#e5f0e9;color:var(--green);font-size:20px;font-weight:750;padding:10px;border-radius:8px}.step-head .badge{margin-left:auto;white-space:nowrap}.badge{font-size:12px;font-weight:700;border-radius:20px;padding:5px 10px;background:#e1f2e7;color:#176441}.badge.fail{background:#fce8dd;color:#9d391b}.badge.info{background:#e6edf7;color:#31577d}.step>p{color:var(--muted);margin:18px 0}.shot{border:1px solid #b9c9c2;background:#112029;border-radius:8px;overflow:hidden;display:block;width:100%;padding:0;cursor:zoom-in}.shot img{display:block;width:100%;height:auto}.comment{margin-top:20px}.comment label{display:block;font-size:13px;font-weight:650;margin-bottom:8px}textarea{font:inherit;width:100%;min-height:82px;resize:vertical;border:1px solid #c8d7ce;border-radius:8px;padding:12px;background:#fcfdfb;color:var(--ink)}textarea:focus{outline:2px solid #56a588;outline-offset:2px}.observations li{margin:10px 0}dl{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:0}dt{font-size:12px;color:var(--muted)}dd{margin:3px 0;font-size:13px;overflow-wrap:anywhere}footer{padding:8px 0 36px;color:var(--muted);font-size:13px}dialog{padding:14px;max-width:98vw;max-height:98vh;border:0;border-radius:12px;background:#152724}dialog::backdrop{background:#000b}dialog img{display:block;max-width:94vw;max-height:86vh;object-fit:contain}dialog button{display:block;margin:0 0 10px auto;padding:6px 14px}a{color:var(--green)}@media(max-width:850px){.layout{display:block;padding:20px 14px}aside{position:static;max-height:none;margin-bottom:24px;columns:2}.summary,.step,.observations{padding:18px}.summary ul,dl{grid-template-columns:1fr}.step-head{flex-wrap:wrap}.step-head .badge{margin-left:0}}@media print{header{background:white;color:#182e32;padding:10px}header p,header .eyebrow{color:#182e32}.actions,aside,.shot+small{display:none}.layout{display:block;padding:0}.step{break-inside:avoid}body{background:white}.comment textarea{min-height:50px}dialog{display:none}}
</style></head><body><header><div class="eyebrow">AGI OS / Проверка реального сценария</div><h1>От запроса до новой системы</h1><p>__SUMMARY__</p><div class="actions"><button id="export">Скачать комментарии · JSON</button><button id="export-html">Скачать HTML с комментариями</button><button class="secondary" id="print">Печать / PDF</button><span id="save-state">Комментарии сохраняются в этом браузере</span></div></header><div class="layout"><aside><strong>Ход проверки</strong>__NAV__<a href="#observations">Замечания и ограничения</a><a href="#environment">Среда прогона</a></aside><main><section class="summary"><div class="eyebrow">Результат · __RESULT__</div><h2>Что подтверждено</h2><ul>__CHECKS__</ul></section>__CARDS__<section id="observations" class="observations"><h2>Замечания к продукту</h2><ul>__ISSUES__</ul></section><section id="environment" class="observations"><h2>Среда и воспроизводимость</h2><dl>__META__</dl></section><footer>Скриншоты сделаны в реальной QEMU/KVM VM. Клик по снимку открывает полный размер. Изображения встроены: HTML работает без сети. Пароль и токены в отчёт не включены. Комментарии никуда не отправляются автоматически — скачайте файл и передайте его для разбора.</footer></main></div><dialog id="zoom"><button id="close-zoom">Закрыть · Esc</button><img alt="Увеличенный скриншот"></dialog><script>
const reportId=__REPORT_ID__, inputs=[...document.querySelectorAll('textarea')], state=document.querySelector('#save-state');
let stored={};try{stored=JSON.parse(localStorage.getItem(reportId)||'{}')}catch(e){state.textContent='Автосохранение недоступно — скачайте комментарии'}
for(const t of inputs){t.value=t.defaultValue||stored[t.id]||'';t.addEventListener('input',()=>{try{localStorage.setItem(reportId,JSON.stringify(Object.fromEntries(inputs.map(x=>[x.id,x.value]))));state.textContent='Комментарии сохранены локально'}catch(e){state.textContent='Скачайте комментарии, чтобы сохранить их'}})}
function download(content,type,name){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
document.querySelector('#export').onclick=()=>download(JSON.stringify({report:reportId,created:new Date().toISOString(),comments:inputs.map(t=>({step:t.dataset.step,title:t.closest('article').querySelector('h2').textContent,comment:t.value})).filter(x=>x.comment.trim())},null,2),'application/json','agi-os-review-comments.json');
document.querySelector('#export-html').onclick=()=>{const clone=document.documentElement.cloneNode(true);inputs.forEach(t=>clone.querySelector('#'+t.id).textContent=t.value);clone.querySelector('#zoom').removeAttribute('open');clone.querySelector('#zoom img').removeAttribute('src');download('<!doctype html>\n'+clone.outerHTML,'text/html','agi-os-review-annotated.html')};
document.querySelector('#print').onclick=()=>window.print();const modal=document.querySelector('#zoom');document.querySelectorAll('.shot').forEach(b=>b.onclick=()=>{modal.querySelector('img').src=b.querySelector('img').src;modal.showModal()});document.querySelector('#close-zoom').onclick=()=>modal.close();modal.onclick=e=>{if(e.target===modal)modal.close()};
</script></body></html>'''
for key,value in {'SUMMARY':esc(data['summary']),'NAV':nav,'RESULT':esc(data['result']),'CHECKS':checks,'CARDS':''.join(cards),'ISSUES':issues,'META':meta,'REPORT_ID':json.dumps(data['id'])}.items():page=page.replace('__'+key+'__',value)
(folder/'index.html').write_text(page)
print(folder/'index.html')
